## Repository 接口与实现

```dart
// domain/repositories/user_repository.dart（接口，在 Domain 层）
abstract interface class UserRepository {
  Future<User> getCurrentUser();
  Future<User> updateProfile({required String name, String? avatarUrl});
  Stream<User> watchCurrentUser();
}
```

```dart
// data/repositories/user_repository_impl.dart（实现，在 Data 层）
@LazySingleton(as: UserRepository)  // injectable 注解
class UserRepositoryImpl implements UserRepository {
  final UserRemoteDataSource _remote;
  final UserLocalDataSource _local;

  const UserRepositoryImpl({
    required UserRemoteDataSource remote,
    required UserLocalDataSource local,
  }) : _remote = remote, _local = local;

  @override
  Future<User> getCurrentUser() async {
    try {
      final dto = await _remote.getCurrentUser();
      await _local.cacheUser(dto);
      return dto.toEntity();
    } on NetworkException {
      // 网络失败时回退到缓存
      final cached = await _local.getCachedUser();
      if (cached == null) rethrow;
      return cached.toEntity();
    }
  }

  @override
  Stream<User> watchCurrentUser() {
    return _local.watchUser().map((dto) => dto.toEntity());
  }
}
```

