## Use Case：封装业务逻辑

```dart
// domain/usecases/get_current_user.dart
@lazySingleton
class GetCurrentUser {
  final UserRepository _repository;
  const GetCurrentUser(this._repository);

  Future<User> call() => _repository.getCurrentUser();
}

// domain/usecases/update_user_profile.dart
class UpdateProfileParams {
  final String name;
  final String? avatarUrl;
  const UpdateProfileParams({required this.name, this.avatarUrl});
}

@lazySingleton
class UpdateUserProfile {
  final UserRepository _repository;
  const UpdateUserProfile(this._repository);

  Future<User> call(UpdateProfileParams params) {
    return _repository.updateProfile(
      name: params.name,
      avatarUrl: params.avatarUrl,
    );
  }
}
```

